input.new_string:
const LOYALTY_YEARS = 2;
const LOYALTY_DISCOUNT_RATE = -0.2;

const isFirstInsurance = (): boolean => true;

const isLongStanding = (customer: Customer): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_YEARS;

// Every policy-wide modifier is a rate on the UNMODIFIED policy base — never on a
// base that already includes the item surcharges. Surcharges carry a positive
// rate, discounts a negative one. Adding a new one means adding a row here.
type PolicyModifier = { appliesTo: (customer: Customer) => boolean; rate: number };

const POLICY_MODIFIERS: PolicyModifier[] = [
  { appliesTo: isFirstInsurance, rate: FIRST_INSURANCE_SURCHARGE_RATE },
  { appliesTo: isLongStanding, rate: LOYALTY_DISCOUNT_RATE },
];

const policyModifierRateFor = (customer: Customer): number =>
  POLICY_MODIFIERS.reduce(
    (rate, modifier) => (modifier.appliesTo(customer) ? rate + modifier.rate : rate),
    0,
  );

const policyModifiersOn = (policyBase: number, customer: Customer): number =>
  policyBase * policyModifierRateFor(customer);
